//! Minds public registry records; linked clinical documents have independent access and rights.
use super::{common,static_list::blocks_for,Adapter,PlanRow};
use crate::guidelines::{doc::{GuidelineDoc,Relation,Rights},fetch::Fetcher,html::{blocks_from_html,sel,text_of},registry::SourceEntry};
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use std::collections::HashSet;
use url::Url;
pub struct JpMinds;
const ROOT:&str="https://minds.jcqhc.or.jp/guidelines_ver/new_guidelines/";
fn catalog(raw:&str,base:&Url)->Result<(Vec<String>,Option<String>)>{let d=Html::parse_document(raw);let root=d.select(&sel("#page-main .page-main-content #list")).next().context("Minds latest list missing")?;let mut links=vec![];for a in root.select(&sel("li > a[href]")){if let Some(u)=a.value().attr("href").and_then(|x|common::link(base,x)){let parsed=Url::parse(&u)?;if parsed.origin()==base.origin()&&parsed.path().starts_with("/summary/"){links.push(u)}}}if links.is_empty(){bail!("Minds latest list contains no records")};let next=d.select(&sel(".wp-pagenavi a[rel='next'][href]")).next().and_then(|a|a.value().attr("href")).and_then(|h|common::link(base,h)).filter(|u|Url::parse(u).map(|x|x.origin()==base.origin()&&x.path().starts_with("/guidelines_ver/new_guidelines/")).unwrap_or(false));Ok((links,next))}
fn record(raw:&str,base:&Url)->Result<(String,String,Vec<serde_json::Value>)>{let d=Html::parse_document(raw);let root=d.select(&sel("main#summary")).next().context("Minds registry root missing")?;let title=root.select(&sel(".article_top .ttl_b h1")).next().map(|x|text_of(&x)).context("Minds registry title missing")?;let body=root.select(&sel("article.article_middle")).next().context("Minds registry metadata missing")?;let mut links=vec![];for a in body.select(&sel("a[href]")){let label=text_of(&a);if !label.contains("【本文】"){continue}let Some(href)=a.value().attr("href").and_then(|h|common::link(base,h))else{continue};let viewer=Url::parse(&href)?;let target=viewer.query_pairs().find(|(k,_)|k=="file").map(|(_,v)|v.into_owned()).unwrap_or(href.clone());let role=if target=="https://minds.jcqhc.or.jp/common/summary/pdf/c00664.pdf"{"full_text_pdf_copy_print_restricted"}else{"full_text_terminal_unverified"};links.push(json!({"url":target,"source_href":href,"label":label,"role":role,"rights":"unknown"}))}let top=root.select(&sel("article.article_top .date_b")).next().map(|x|x.html()).unwrap_or_default();Ok((title,format!("{top}{}",body.html()),links))}
fn native_fields(raw:&str,base:&Url)->Result<Vec<serde_json::Value>>{let d=Html::parse_document(raw);let root=d.select(&sel("main#summary")).next().context("Minds registry root missing")?;let mut fields=vec![];for row in root.select(&sel("article.left_bottom_b .info_i")){let Some(label)=row.select(&sel(".info_l h3")).next().map(|x|text_of(&x))else{continue};let Some(v)=row.select(&sel(".info_r")).next()else{continue};let value=text_of(&v);if value.is_empty(){continue}let links=v.select(&sel("a[href]")).filter_map(|a|a.value().attr("href").and_then(|h|common::link(base,h)).map(|url|json!({"url":url,"label":text_of(&a)}))).collect::<Vec<_>>();fields.push(json!({"label":label,"value":value,"links":links,"source_url":base.as_str(),"scope":"minds_registry_record"}));}for row in root.select(&sel(".article_top > .date_b p")){let text=text_of(&row);if let Some((label,value))=text.split_once('：'){fields.push(json!({"label":label,"value":value,"links":[],"source_url":base.as_str(),"scope":"minds_registry_page"}));}}for row in root.select(&sel(".category_b .main_content")){let Some(label)=row.select(&sel("p.parent_category")).next().map(|x|text_of(&x))else{continue};for v in row.select(&sel("p:not(.parent_category)")){let value=text_of(&v);if !value.is_empty(){fields.push(json!({"label":label,"value":value,"links":[],"source_url":base.as_str(),"scope":"minds_registry_record"}));}}}Ok(fields)}
const JSH:&str="https://www.jpnsh.jp/guideline.html";
fn jsh_landing(raw:&str,base:&Url)->Result<serde_json::Value>{let d=Html::parse_document(raw);let root=d.select(&sel("#main")).next().context("JSH source content missing")?;if !root.select(&sel("h2")).any(|h|text_of(&h).contains("高血圧管理・治療ガイドライン")){bail!("JSH source title missing")};let notice=root.select(&sel("p")).map(|p|text_of(&p)).find(|s|s.contains("ダウンロードおよび印刷不可")&&s.contains("許諾なく")).context("JSH view-only notice missing")?;let mut assets=vec![];for a in root.select(&sel("a[href]")){let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h))else{continue};let role=if url=="https://jpnsh.box.com/v/jsh2025-publish-pdf"{"full_guideline_view_only_restricted"}else if url=="https://www.lifescience.co.jp/shop2/p_item/JSH2025_errata.pdf"{"errata_unverified"}else if url=="https://www.jpnsh.jp/guideline_n.html"{"digest_product_page"}else if url=="https://www.jpnsh.jp/guideline_g.html"{"patient_booklet_page"}else if url=="https://www.jpnsh.jp/member/m_guideline.php"{"member_only_slides"}else{continue};assets.push(json!({"url":url,"label":text_of(&a),"role":role,"source_url":base.as_str(),"rights":"unknown"}));}if !assets.iter().any(|x|x["role"]=="full_guideline_view_only_restricted"){bail!("JSH view-only source link missing")};Ok(json!({"notice":notice,"assets":assets,"source_url":base.as_str()}))}
fn snapshot(title:&str,body:&str,links:&[serde_json::Value])->Result<String>{let serialized=serde_json::to_string(&(title,body,links))?;let nonce=regex::Regex::new(r#"_wpnonce=[^&"']+"#)?;Ok(crate::common::sha256_hex(nonce.replace_all(&serialized,"_wpnonce=<volatile>").as_bytes()))}
fn issue(s:&SourceEntry,u:String,e:String)->PlanRow{PlanRow{source_id:s.id.clone(),doc_key:format!("minds-{}-unresolved",common::short_hash(&u)),url:u,title:None,rendition:None,version:None,extra:json!({"discovery_error":e})}}
#[async_trait::async_trait]impl Adapter for JpMinds{
 async fn discover(&self,s:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let mut next=Some(s.catalog_url.as_deref().unwrap_or(ROOT).to_string());let mut seen=HashSet::new();let mut rows=vec![];while let Some(url)=next.take(){if !seen.insert(url.clone()){rows.push(issue(s,url,"Minds pagination cycle".into()));break}if seen.len()>500{rows.push(issue(s,url,"Minds pagination bound reached".into()));break}let p=match f.get_ok(&url).await{Ok(x)=>x,Err(e)=>{rows.push(issue(s,url,format!("Minds page unavailable: {e:#}")));break}};let b=Url::parse(&p.record.final_url)?;if b.origin()!=Url::parse(ROOT)?.origin(){bail!("Minds redirect outside source")};let (urls,n)=if b.path().starts_with("/summary/"){(vec![url.clone()],None)}else{catalog(&p.text(),&b)?};next=n;for u in urls{let p=match f.get_ok(&u).await{Ok(x)=>x,Err(e)=>{rows.push(issue(s,u,format!("Minds record unavailable: {e:#}")));if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}};let b=Url::parse(&p.record.final_url)?;if b.origin()!=Url::parse(ROOT)?.origin(){rows.push(issue(s,u,"Minds record redirect outside source".into()));continue}match record(&p.text(),&b){Ok((title,body,links))=>{let hash=snapshot(&title,&body,&links)?;let mut external_sha=None;let mut external_error=None;let mut external_assets=None;if links.iter().any(|x|x["url"]==JSH){match f.get_ok(JSH).await{Ok(ext)=>{if ext.record.final_url!=JSH{external_error=Some("JSH redirected from source target".to_string())}else{match jsh_landing(&ext.text(),&Url::parse(JSH)?){Ok(data)=>{external_sha=Some(ext.record.sha256);external_assets=Some(data)},Err(e)=>external_error=Some(format!("JSH landing template: {e:#}"))}}},Err(e)=>external_error=Some(format!("JSH landing unavailable: {e:#}"))}}let identity=crate::common::sha256_hex(format!("{}:{}",hash,external_sha.as_deref().unwrap_or("unavailable")).as_bytes());rows.push(PlanRow{source_id:s.id.clone(),doc_key:format!("minds-{}-{}",common::short_hash(&u),&identity[..12]),url:u.clone(),title:Some(title.clone()),rendition:Some("html".into()),version:None,extra:json!({"snapshot":hash,"jsh_sha256":external_sha,"jsh_error":external_error})});if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}if let Some(data)=external_assets{for asset in data["assets"].as_array().into_iter().flatten(){if asset["role"]!="errata_unverified"{continue}let Some(target)=asset["url"].as_str()else{continue};match f.get_ok(target).await{Ok(p) if p.is_pdf()&&Url::parse(&p.record.final_url)?.host_str()==Url::parse(target)?.host_str()=>{let sha=p.record.sha256;rows.push(PlanRow{source_id:s.id.clone(),doc_key:format!("minds-errata-{}-{}",common::short_hash(target),&sha[..12]),url:target.into(),title:Some(format!("{} — {}",title,asset["label"].as_str().unwrap_or(""))),rendition:Some("pdf".into()),version:asset["label"].as_str().map(String::from),extra:json!({"role":"source_errata","pdf_sha256":sha,"registry_url":u,"landing_url":JSH,"label":asset["label"]})})},Ok(_)=>rows.push(issue(s,target.into(),"JSH errata is not an independently validated same-host PDF".into())),Err(e)=>rows.push(issue(s,target.into(),format!("JSH errata unavailable: {e:#}")))}if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}}},Err(e)=>rows.push(issue(s,u,format!("Minds record template: {e:#}")))}if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}}Ok(rows)}
 async fn extract(&self,s:&SourceEntry,f:&Fetcher,r:&PlanRow)->Result<GuidelineDoc>{if let Some(e)=r.extra["discovery_error"].as_str(){bail!("{e}")};if r.rendition.as_deref()==Some("pdf"){let p=f.get_ok(&r.url).await?;if !p.is_pdf()||Url::parse(&p.record.final_url)?.host_str()!=Url::parse(&r.url)?.host_str()||r.extra["pdf_sha256"].as_str()!=Some(p.record.sha256.as_str()){bail!("JSH errata changed or redirected; re-plan")};let(blocks,mut warnings,_)=blocks_for(&p,None,30).await?;if blocks.is_empty(){bail!("JSH errata PDF has no converted text")};warnings.push("Source-labelled errata and update information are a separate asset, not the complete guideline; physical pages, table alignment and rights remain unverified.".into());return Ok(GuidelineDoc{source_id:s.id.clone(),doc_key:r.doc_key.clone(),work_key:Some(format!("minds-errata-{}",common::short_hash(&r.url))),url:r.url.clone(),title:r.title.clone().unwrap_or_else(||r.url.clone()),item_type:Some("erratum".into()),version:r.version.clone(),status:"unknown".into(),rights:Rights{status:"unknown".into(),..Default::default()},relations:vec![Relation{rel:"erratum_to".into(),target:JSH.into(),scope:Some("Source-labelled 2025 guideline errata; exact corrections remain in PDF".into()),evidence_url:Some(JSH.into())}],blocks,fetches:vec![p.record],warnings,..Default::default()})}let p=f.get_ok(&r.url).await?;let b=Url::parse(&p.record.final_url)?;if b.origin()!=Url::parse(ROOT)?.origin(){bail!("Minds record redirect outside source")};let(title,body,links)=record(&p.text(),&b)?;let hash=snapshot(&title,&body,&links)?;if r.extra["snapshot"].as_str()!=Some(hash.as_str()){bail!("Minds record changed; re-plan")};let fields=native_fields(&p.text(),&b)?;let mut external=None;let mut fetches=vec![p.record.clone()];if let Some(expected)=r.extra["jsh_sha256"].as_str(){let ext=f.get_ok(JSH).await?;if ext.record.final_url!=JSH||ext.record.sha256!=expected{bail!("JSH source landing changed; re-plan")};external=Some(jsh_landing(&ext.text(),&Url::parse(JSH)?)?);fetches.push(ext.record);}let(blocks,mut warnings)=blocks_from_html(&body,Some(&b),None);if let Some(e)=r.extra["jsh_error"].as_str(){warnings.push(e.to_string())}warnings.push("Minds registry metadata and clinical-question index are not the full guideline. Linked publisher documents require independent access, rights and content validation; the c00664 PDF has observed copy/print restrictions. Latest-edition pagination is not a complete inventory.".into());Ok(GuidelineDoc{source_id:s.id.clone(),doc_key:r.doc_key.clone(),work_key:Some(format!("minds-{}",common::short_hash(&r.url))),url:r.url.clone(),title,item_type:Some("registry_record".into()),status:"unknown".into(),rights:Rights{status:"unknown".into(),..Default::default()},blocks,attachments:links,search_metadata:json!({"native_fields":fields,"record_html":body,"external_publisher_landing":external}),fetches,warnings,..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const CAT:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/research-1.html"));const PAIN:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/research-2.html"));const HTN:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/research-3.html"));
#[test]fn genuine_records_keep_terminal_roles_and_dates(){let(urls,next)=catalog(CAT,&Url::parse(ROOT).unwrap()).unwrap();assert_eq!(urls.len(),10);assert!(next.unwrap().ends_with("/page/2/"));let(t,b,l)=record(PAIN,&Url::parse("https://minds.jcqhc.or.jp/summary/c00664/").unwrap()).unwrap();assert!(t.contains("慢性疼痛"));assert!(b.contains("2021年11月24日")&&b.contains("2022年5月24日"));assert!(l.iter().any(|x|x["url"]=="https://minds.jcqhc.or.jp/common/summary/pdf/c00664.pdf"&&x["role"]=="full_text_pdf_copy_print_restricted"));let(_,_,l)=record(HTN,&Url::parse("https://minds.jcqhc.or.jp/summary/c00890/").unwrap()).unwrap();assert!(l.iter().any(|x|x["url"]=="https://www.jpnsh.jp/guideline.html"&&x["role"]=="full_text_terminal_unverified"));}
#[tokio::test]async fn genuine_record_extract_does_not_convert_restricted_pdf(){let u="https://minds.jcqhc.or.jp/summary/c00664/";let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(u,PAIN.as_bytes(),"text/html");let s:SourceEntry=serde_json::from_value(json!({"id":"jp_minds","access":"public","enabled":true,"catalog_url":u})).unwrap();let rows=JpMinds.discover(&s,&f,Some(1)).await.unwrap();assert_eq!(rows.len(),1);let d=JpMinds.extract(&s,&f,&rows[0]).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("registry_record"));assert_eq!(d.rights.status,"unknown");assert!(d.warnings.iter().any(|x|x.contains("copy/print restrictions")));assert!(d.attachments.iter().any(|x|x["role"]=="full_text_pdf_copy_print_restricted"));let fs=d.search_metadata["native_fields"].as_array().unwrap();for (label,value) in [("発行年月日","2021年6月30日"),("発行元","真興交易 医書出版部"),("新旧属性","最新版"),("公開ステータス","本文公開中"),("初回投稿日","2021年11月24日"),("ページ更新日","2022年5月24日"),("トピックス","痛み")] {assert!(fs.iter().any(|f|f["label"]==label&&f["value"]==value&&f["source_url"]==u),"missing {label}");}assert!(d.search_metadata["record_html"].as_str().unwrap().contains("書誌情報"));}
}

#[cfg(all(test, feature = "guideline-fixtures"))]mod public_round_ab{use super::*;const PAGE2:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/page-2.html"));const CAT:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/research-1.html"));const JSH_HTML:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/jsh-landing.html"));
#[test]fn real_page_two_follows_pagination(){let u=Url::parse("https://minds.jcqhc.or.jp/guidelines_ver/new_guidelines/page/2/").unwrap();let(rows,next)=catalog(PAGE2,&u).unwrap();assert_eq!(rows.len(),10);assert_eq!(rows[0],"https://minds.jcqhc.or.jp/summary/c00906/");assert_eq!(next.unwrap(),"https://minds.jcqhc.or.jp/guidelines_ver/new_guidelines/page/3/");}
#[tokio::test]async fn bounded_discovery_reaches_source_page_two(){let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,CAT.as_bytes(),"text/html");f.seed_cache_for_tests("https://minds.jcqhc.or.jp/guidelines_ver/new_guidelines/page/2/",PAGE2.as_bytes(),"text/html");let s:SourceEntry=serde_json::from_value(json!({"id":"jp_minds","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=JpMinds.discover(&s,&f,Some(11)).await.unwrap();assert_eq!(rows.len(),11);assert_eq!(rows[10].url,"https://minds.jcqhc.or.jp/summary/c00906/");assert!(rows[10].extra["discovery_error"].is_string());}
#[tokio::test]async fn source_landing_is_pinned_and_view_only_notice_preserved(){let url="https://minds.jcqhc.or.jp/summary/c00890/";let htn=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/research-3.html"));let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(url,htn.as_bytes(),"text/html");f.seed_cache_for_tests(JSH,JSH_HTML.as_bytes(),"text/html");let s:SourceEntry=serde_json::from_value(json!({"id":"jp_minds","access":"public","enabled":true,"catalog_url":url})).unwrap();let rows=JpMinds.discover(&s,&f,Some(1)).await.unwrap();let d=JpMinds.extract(&s,&f,&rows[0]).await.unwrap();let e=&d.search_metadata["external_publisher_landing"];assert!(e["notice"].as_str().unwrap().contains("ダウンロードおよび印刷不可"));assert!(e["assets"].as_array().unwrap().iter().any(|x|x["role"]=="full_guideline_view_only_restricted"));assert_eq!(d.fetches.len(),2);assert_eq!(d.item_type.as_deref(),Some("registry_record"));}
#[test]fn source_society_page_distinguishes_restricted_full_and_errata(){let d=Html::parse_document(JSH_HTML);let root=d.select(&sel("#main")).next().unwrap();let text=text_of(&root);assert!(text.contains("ダウンロードおよび印刷不可")&&text.contains("許諾なく"));let links=root.select(&sel("a[href]")).map(|a|a.value().attr("href").unwrap().to_string()).collect::<Vec<_>>();assert!(links.iter().any(|u|u=="https://jpnsh.box.com/v/jsh2025-publish-pdf"));assert!(links.iter().any(|u|u=="https://www.lifescience.co.jp/shop2/p_item/JSH2025_errata.pdf"));assert!(!links.iter().any(|u|u=="data/jsh2025/CQ1.pdf"));assert!(links.iter().any(|u|u=="guideline_n.html"));assert!(links.iter().any(|u|u=="https://www.jpnsh.jp/member/m_guideline.php"));}
}

#[cfg(all(test, feature = "guideline-fixtures"))]mod errata_round_ac{use super::*;const PAGE:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/research-3.html"));const LANDING:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/jsh-landing.html"));const PDF:&[u8]=include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/jp_minds/jsh-errata.pdf"));
#[tokio::test]async fn source_errata_is_a_separate_asset_with_revision_guard(){let parent="https://minds.jcqhc.or.jp/summary/c00890/";let pdf="https://www.lifescience.co.jp/shop2/p_item/JSH2025_errata.pdf";let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,2<<20,"").unwrap();f.seed_cache_for_tests(parent,PAGE.as_bytes(),"text/html");f.seed_cache_for_tests(JSH,LANDING.as_bytes(),"text/html");f.seed_cache_for_tests(pdf,PDF,"application/pdf");let s:SourceEntry=serde_json::from_value(json!({"id":"jp_minds","access":"public","enabled":true,"catalog_url":parent})).unwrap();let rows=JpMinds.discover(&s,&f,Some(2)).await.unwrap();assert_eq!(rows.len(),2);let d=JpMinds.extract(&s,&f,&rows[1]).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("erratum"));assert!(d.version.as_deref().unwrap().contains("2026.3.31"));assert!(d.relations.iter().any(|r|r.rel=="erratum_to"&&r.target==JSH));assert!(d.blocks.iter().any(|b|b.text.contains("正誤表")));assert_eq!(d.rights.status,"unknown");let mut stale=rows[1].clone();stale.extra["pdf_sha256"]=json!("wrong");assert!(JpMinds.extract(&s,&f,&stale).await.is_err());}
}
